var scene=UnityEngine.SceneManagement.SceneManager.GetSceneByName("Safehouse");var map=scene.GetRootGameObjects().Single(g=>g.name=="Map");var root=map.transform.Find("Pawnshop_Forecourt62");if(root==null)throw new System.Exception("Forecourt missing");
var mats=root.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Where(m=>m!=null).Distinct().ToArray();
var invalid=mats.Where(m=>m.shader.name!="BRB/GameLit"||UnityEditor.ShaderUtil.GetShaderMessages(m.shader).Any(e=>e.severity==UnityEditor.Rendering.ShaderCompilerMessageSeverity.Error)).Select(m=>m.name).ToArray();
var corridor=new Bounds(new Vector3(34,.8f,36),new Vector3(3.4f,1.5f,5));var blocked=root.Cast<Transform>().Where(t=>t.GetComponent<MeshFilter>()==null&&t.GetComponent<Light>()==null).SelectMany(t=>t.GetComponentsInChildren<Renderer>()).Where(r=>r.bounds.Intersects(corridor)).Select(r=>r.name).ToArray();
int missing=map.GetComponentsInChildren<Transform>(true).Sum(t=>UnityEditor.GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject));
if(invalid.Length!=0||blocked.Length!=0||missing!=0||root.GetComponentsInChildren<Collider>().Length!=0)throw new System.Exception("Forecourt validation failed: "+string.Join(",",invalid.Concat(blocked)));
var result=new{playing=UnityEditor.EditorApplication.isPlaying,scene=scene.path,missingScripts=missing,materials=mats.Length,invalidMaterials=invalid,entranceClearWidth=3.4f,corridorVisualObstacles=blocked,newColliders=0,reviewCameras=UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsSortMode.None).Count(c=>c.name.Contains("ReviewCamera")),mainCameraRotation=Camera.main.transform.eulerAngles.ToString(),porchLights=root.GetComponentsInChildren<Light>().Length};
var json=Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented);System.IO.File.WriteAllText("D:/Demo/ArtWork/TownFinish62/"+(UnityEditor.EditorApplication.isPlaying?"RuntimeValidation":"EditorValidation")+".json",json);return json;
